VALUES ('doc-09-mitre-attack-p0-17446', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bisonal](https://attack.mitre.org/software/S0268) has launched cmd.exe and used the ShellExecuteW() API function to execute commands on the system.(Citation: Unit 42 Bisonal July 2018)(Citation: Kaspersky CactusPete Aug 2020)(Citation: Talos Bisonal Mar 2020)", "external_references": [{"description": "Hayashi, K., Ray, V. (2018, July 31). Bisonal Malware Used in Attacks Against Russia and South Korea. Retrieved August 7, 2018.", "source_name": "Unit 42 Bisonal July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-bisonal-malware-used-attacks-russia-south-korea/"}, {"description": "Zykov, K. (2020, August 13). CactusPete APT group’s updated Bisonal backdoor. Retrieved May 5, 2021.", "source_name": "Kaspersky CactusPete Aug 2020", "url": "https://securelist.com/cactuspete-apt-groups-updated-bisonal-backdoor/97962/"}, {"description": "Mercer, W., et al. (2020, March 5). Bisonal: 10 years of play. Retrieved January 26, 2022.", "source_name": "Talos Bisonal Mar 2020", "url": "https://blog.talosintelligence.com/2020/03/bisonal-10-years-of-play.html"}], "id": "relationship--ca3f0924-306a-409e-a1b6-135b781f3dbf", "modified": "2026-04-29T14:23:06.202Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--65ffc206-d7c1-45b3-b543-f6b726e7840d", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17446', 0, 136, '09-mitre-attack', 'retrieved', 'F301579B6E962ACA9AB1B24093F1E6A9F140C2329AFDDA5A92F6A872C8DBF7CB',