VALUES ('doc-09-mitre-attack-p0-17451', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-01-26T22:07:08.667Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bisonal](https://attack.mitre.org/software/S0268) has renamed malicious code to `msacm32.dll` to hide within a legitimate library; earlier versions were disguised as `winhelp`.(Citation: Talos Bisonal Mar 2020) ", "external_references": [{"description": "Mercer, W., et al. (2020, March 5). Bisonal: 10 years of play. Retrieved January 26, 2022.", "source_name": "Talos Bisonal Mar 2020", "url": "https://blog.talosintelligence.com/2020/03/bisonal-10-years-of-play.html"}], "id": "relationship--e9ddb0b6-298e-4061-b194-c9ea5d49c6d0", "modified": "2026-04-29T14:23:06.243Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--65ffc206-d7c1-45b3-b543-f6b726e7840d", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17451', 0, 78, '09-mitre-attack', 'retrieved', '7379C9A1348EB4B6FD52F301ED0A4D00302637F50E0CED33AE81EC899740A620', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
