VALUES ('doc-09-mitre-attack-p0-17453', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:50:46.515Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MultiLayer Wiper](https://attack.mitre.org/software/S1135) reboots the infected system following wiping and related tasks to prevent system recovery.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--20d59bcb-04cd-4581-a18f-4f77dd96027c", "modified": "2026-04-29T14:23:05.950Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--663d7dee-5a47-459e-a5ef-e850a94a8ee5", "spec_version": "2.1", "target_ref": "attack-pattern--ff73aa03-0090-4464-83ac-f89e233c02bc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17453', 0, 83, '09-mitre-attack', 'retrieved', 'E3BCDF70760B88E69BCA047BEFD515E7B6D42A6A94E03D46611082B4E6D8276E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
