VALUES ('doc-09-mitre-attack-p0-17454', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:47:41.717Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MultiLayer Wiper](https://attack.mitre.org/software/S1135) uses a batch script to clear file system cache memory via the ProcessIdleTasks export in advapi32.dll as an anti-analysis and anti-forensics technique.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--27e8b9dc-9b72-4e69-b093-c80c81cf6d59", "modified": "2026-04-29T14:23:05.959Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--663d7dee-5a47-459e-a5ef-e850a94a8ee5", "spec_version": "2.1", "target_ref": "attack-pattern--799ace7f-e227-4411-baa0-8868704f2a69", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17454', 0, 92, '09-mitre-attack', 'retrieved', '507E9CE38A86ACD91716553CC1E8D9D3DD8E0ED1235422CE6EAECA0C6AA2A8E1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
