VALUES ('doc-09-mitre-attack-p0-17506', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:12:50.160Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has used process hollowing leveraging a legitimate program such as “BitLockerToGo.exe” to inject a malicious payload.(Citation: Qualys LummaStealer 2024)", "external_references": [{"description": "Vishwajeet Kumar, Qualys. (2024, October 20). Unmasking Lumma Stealer: Analyzing Deceptive Tactics with Fake CAPTCHA. Retrieved March 22, 2025.", "source_name": "Qualys LummaStealer 2024", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2024/10/20/unmasking-lumma-stealer-analyzing-deceptive-tactics-with-fake-captcha"}], "id": "relationship--3e7ca7c1-39f9-4549-8446-0610f8c0c1ea", "modified": "2026-04-29T14:23:06.010Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--b200542e-e877-4395-875b-cf1a44537ca4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17506', 0, 77, '09-mitre-attack', 'retrieved', '1881184409934B4A26958B9192AE46472D41E26F22A55C8F0E2392D177B99F2D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
