VALUES ('doc-09-mitre-attack-p0-17508', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:53:27.242Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has queried system resources on the victim device to identify if it is executing in a sandbox or virtualized environments, checking usernames, conducting WMI queries for system details, checking for files commonly found in virtualized environments, searching system services, and inspecting process names.(Citation: Fortinet LummaStealer 2024) [Lumma Stealer](https://attack.mitre.org/software/S1213) has checked system GPU configurations for sandbox detection.(Citation: TrendMicro LummaStealer 2025)", "external_references": [{"description": "Buddy Tancio, Fe Cureg, and Jovit Samaniego, Trend Micro. (2025, January 30). Lumma Stealer’s GitHub-Based Delivery Explored via Managed Detection and Response. Retrieved March 22, 2025.", "source_name": "TrendMicro LummaStealer 2025", "url": "https://www.trendmicro.com/en_us/research/25/a/lumma-stealers-github-based-delivery-via-mdr.html"}, {"description": "Cara Lin, Fortinet. (2024, January 8). Deceptive Cracked Software Spreads Lumma Variant on YouTube. Retrieved March 22, 2025.", "source_name": "Fortinet LummaStealer 2024", "url": "https://www.fortinet.com/blog/threat-research/lumma-variant-on-youtube"}], "id": "relationship--5a8ea0ac-7a51-4440-898b-a70ee71d06a4", "modified": "2026-04-29T14:23:06.049Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17508', 0, 149, '09-mitre-attack', 'retrieved', '2542466F7403E405E9CE91AE0872FB800F91FC8E1EC5223D0666200FA03F0E1E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
