VALUES ('doc-09-mitre-attack-p0-17510', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:32:36.641Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has leveraged legitimate applications to then side-load malicious DLLs during execution.(Citation: Cybereason LumaStealer Undated)", "external_references": [{"description": "Cybereaon Security Services Team. (n.d.). Your Data Is Under New Lummanagement: The Rise of LummaStealer. Retrieved March 22, 2025.", "source_name": "Cybereason LumaStealer Undated", "url": "https://www.cybereason.com/blog/threat-analysis-rise-of-lummastealer"}], "id": "relationship--5fd27d34-7250-4c1d-81ce-683cdb527b9c", "modified": "2026-04-29T14:23:06.055Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17510', 0, 72, '09-mitre-attack', 'retrieved', 'D46C2BB20904270982EFC92584D55AAFBC84A023618FB92349AA677EA936BED8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
