VALUES ('doc-09-mitre-attack-p0-17512', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:29:28.828Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has created registry keys to maintain persistence using `HKCU:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Run`.(Citation: Cybereason LumaStealer Undated)(Citation: Netskope LummaStealer 2025)", "external_references": [{"description": "Cybereaon Security Services Team. (n.d.). Your Data Is Under New Lummanagement: The Rise of LummaStealer. Retrieved March 22, 2025.", "source_name": "Cybereason LumaStealer Undated", "url": "https://www.cybereason.com/blog/threat-analysis-rise-of-lummastealer"}, {"description": "Leandro Fróes, Netskope. (2025, January 23). Lumma Stealer: Fake CAPTCHAs & New Techniques to Evade Detection. Retrieved March 22, 2025.", "source_name": "Netskope LummaStealer 2025", "url": "https://www.netskope.com/blog/lumma-stealer-fake-captchas-new-techniques-to-evade-detection"}], "id": "relationship--827bdd59-c6b9-43fe-9004-ab9a740e323a", "modified": "2026-04-29T14:23:06.104Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17512', 0, 100, '09-mitre-attack', 'retrieved', '6C320BFE1C692BA55E20D405FF8166DC17694022D8D28F856F7B34AA00B5173C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
