VALUES ('doc-09-mitre-attack-p0-17514', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T16:01:14.425Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has configured a custom user data directory such as a folder within `%USERPROFILE%\\AppData\\Roaming` for staging data.(Citation: TrendMicro LummaStealer 2025)", "external_references": [{"description": "Buddy Tancio, Fe Cureg, and Jovit Samaniego, Trend Micro. (2025, January 30). Lumma Stealer’s GitHub-Based Delivery Explored via Managed Detection and Response. Retrieved March 22, 2025.", "source_name": "TrendMicro LummaStealer 2025", "url": "https://www.trendmicro.com/en_us/research/25/a/lumma-stealers-github-based-delivery-via-mdr.html"}], "id": "relationship--8c9728bd-f58c-4a78-8b4d-63e8fe8cce31", "modified": "2026-04-29T14:23:06.117Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17514', 0, 84, '09-mitre-attack', 'retrieved', '4D4A81286B3FDD57B3AA7838FAFB6DCA67C9AD07E35D758C56275CE832BCCB5E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
