VALUES ('doc-09-mitre-attack-p0-17515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:16:25.955Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has exfiltrated collected data over existing HTTP and HTTPS C2 channels.(Citation: Qualys LummaStealer 2024)(Citation: Fortinet LummaStealer 2024)", "external_references": [{"description": "Cara Lin, Fortinet. (2024, January 8). Deceptive Cracked Software Spreads Lumma Variant on YouTube. Retrieved March 22, 2025.", "source_name": "Fortinet LummaStealer 2024", "url": "https://www.fortinet.com/blog/threat-research/lumma-variant-on-youtube"}, {"description": "Vishwajeet Kumar, Qualys. (2024, October 20). Unmasking Lumma Stealer: Analyzing Deceptive Tactics with Fake CAPTCHA. Retrieved March 22, 2025.", "source_name": "Qualys LummaStealer 2024", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2024/10/20/unmasking-lumma-stealer-analyzing-deceptive-tactics-with-fake-captcha"}], "id": "relationship--9726fa12-6427-4e71-8acb-c3438e7ad5b0", "modified": "2026-04-29T14:23:06.131Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--92d7da27-2d91-488e-a00c-059dc162766d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17515', 0, 100, '09-mitre-attack', 'retrieved', '91423A80E804B7E32DC936EDA2BE1BA1C0C6EE1C1B02CF3FABB2283C1712A28F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
