VALUES ('doc-09-mitre-attack-p0-17531', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-22T15:56:02.549Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lumma Stealer](https://attack.mitre.org/software/S1213) has utilized the .NET `ProcessStartInfo` class features to prevent the process from creating a visible window through setting the `CreateNoWindow` setting to “True,” which allows the executed command or script to run without displaying a command prompt window.(Citation: Fortinet LummaStealer 2024)", "external_references": [{"description": "Cara Lin, Fortinet. (2024, January 8). Deceptive Cracked Software Spreads Lumma Variant on YouTube. Retrieved March 22, 2025.", "source_name": "Fortinet LummaStealer 2024", "url": "https://www.fortinet.com/blog/threat-research/lumma-variant-on-youtube"}], "id": "relationship--eeeb81ca-b5df-4477-918b-a70b8097da28", "modified": "2026-04-29T14:23:06.250Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--674c514f-e485-47a8-9d49-1aaa70de155b", "spec_version": "2.1", "target_ref": "attack-pattern--cbb66055-0325-4111-aca0-40547b6ad5b0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17531', 0, 98, '09-mitre-attack', 'retrieved', 'EA4EBC33B62217EBD9D2BF66F38D81639575364143E3AC740B27FF00873AAE4D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
