VALUES ('doc-09-mitre-attack-p0-17569', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Truvasys](https://attack.mitre.org/software/S0178) adds a Registry Run key to establish persistence.(Citation: Microsoft Win Defender Truvasys Sep 2017)", "external_references": [{"description": "Microsoft. (2017, September 15). Backdoor:Win32/Truvasys.A!dha. Retrieved November 30, 2017.", "source_name": "Microsoft Win Defender Truvasys Sep 2017", "url": "https://www.microsoft.com/en-us/wdsi/threats/malware-encyclopedia-description?Name=Backdoor:Win32/Truvasys.A!dha"}], "id": "relationship--55df3b40-b130-4313-9064-6b0fc56564d0", "modified": "2026-04-29T14:23:06.042Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--691c60e2-273d-4d56-9ce6-b67e0f8719ad", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17569', 0, 64, '09-mitre-attack', 'retrieved', '1CC0956DA08B37697A5720055D8CF5CBFB007629409000AC904E2A8C168B4FBF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
