VALUES ('doc-09-mitre-attack-p0-17583', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Remsec](https://attack.mitre.org/software/S0125) loader implements itself with the name Security Support Provider, a legitimate Windows function. Various [Remsec](https://attack.mitre.org/software/S0125) .exe files mimic legitimate file names used by Microsoft, Symantec, Kaspersky, Hewlett-Packard, and VMWare. [Remsec](https://attack.mitre.org/software/S0125) also disguised malicious modules using similar filenames as custom network encryption software on victims.(Citation: ComputerWeekly Strider)(Citation: Kaspersky ProjectSauron Full Report)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2016, August 9). The ProjectSauron APT. Retrieved August 17, 2016.", "source_name": "Kaspersky ProjectSauron Full Report", "url": "https://securelist.com/files/2016/07/The-ProjectSauron-APT_research_KL.pdf"}, {"description": "Warwick Ashford. (2016, August 8). Strider cyber attack group deploying malware for espionage. Retrieved January 10, 2024.", "source_name": "ComputerWeekly Strider", "url": "https://www.computerweekly.com/news/450302128/Strider-cyber-attack-group-deploying-malware-for-espionage"}], "id": "relationship--48b75b8b-5bef-4f99-baa8-5fa978d371d2", "modified": "2026-04-29T14:23:06.024Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--69d6f4a9-fcf0-4f51-bca7-597c51ad0bb8", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17583', 0, 130, '09-mitre-attack', 'retrieved', 'F10B3DB7A973A11850F0AC71B95EBCDC46DBBABE038AE749429BB0D38920CF26', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
