VALUES ('doc-09-mitre-attack-p0-17642', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Rover](https://attack.mitre.org/software/S0090) automatically collects files from the local system and removable drives based on a predefined list of file extensions on a regular timeframe.(Citation: Palo Alto Rover)", "external_references": [{"description": "Ray, V., Hayashi, K. (2016, February 29). New Malware ‘Rover’ Targets Indian Ambassador to Afghanistan. Retrieved February 29, 2016.", "source_name": "Palo Alto Rover", "url": "http://researchcenter.paloaltonetworks.com/2016/02/new-malware-rover-targets-indian-ambassador-to-afghanistan/"}], "id": "relationship--121a09bd-f603-4476-a149-a3cba52f268c", "modified": "2026-04-29T14:23:05.929Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6b616fc1-1505-48e3-8b2c-0d19337bff38", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17642', 0, 82, '09-mitre-attack', 'retrieved', '552FFE8B060A106871687F3F41292AB72C1E6FDAF6C159FF3316987F5420ECAD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
