VALUES ('doc-09-mitre-attack-p0-17800', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-17T09:42:54.982Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PureCrypter](https://attack.mitre.org/software/S9019) has used SmartAssembly and NET-Reactor for string encryption and control flow obfuscation.(Citation: Zscaler PureCrypter JUN 2022)(Citation: Check Point Blind Eagle MAR 2025)", "external_references": [{"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "Dumont, R. (2022, June 13). Technical Analysis of PureCrypter: A Fully-Functional Loader Distributing Remote Access Trojans and Information Stealers. Retrieved April 16, 2026.", "source_name": "Zscaler PureCrypter JUN 2022", "url": "https://www.zscaler.com/blogs/security-research/technical-analysis-purecrypter"}], "id": "relationship--fa83b0ea-65b1-44da-9229-542efc06a3ae", "modified": "2026-04-29T14:23:06.265Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f22487c-dbbf-4a5b-85ca-a8c85e8f2f80", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17800', 0, 110, '09-mitre-attack', 'retrieved', '8713ACA668A24F04C0DDE58BC1AA3F4F7A6A4628944B0C7E7C60B0E05A3ABD0A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
