VALUES ('doc-09-mitre-attack-p0-17801', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-04T18:09:38.950Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Akira](https://attack.mitre.org/software/S1129) examines files prior to encryption to determine if they meet requirements for encryption and can be encrypted by the ransomware. These checks are performed through native Windows functions such as GetFileAttributesW .(Citation: Kersten Akira 2023)(Citation: Cisco Akira Ransomware OCT 2024)", "external_references": [{"description": "Max Kersten & Alexandre Mundo. (2023, November 29). Akira Ransomware. Retrieved April 4, 2024.", "source_name": "Kersten Akira 2023", "url": "https://www.trellix.com/blogs/research/akira-ransomware/"}, {"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}], "id": "relationship--079b3956-d020-4b9d-a230-e43b391e261f", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6b2353-4b39-40ce-9d6d-d00b7a61e656", "spec_version": "2.1", "target_ref": "attack-pattern--7bc57495-ea59-4380-be31-a64af124ef18", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17801', 0, 118, '09-mitre-attack', 'retrieved', 'AA911D360E144E2D63CB084A1CAF18296B218156CC19F4B33168764BB4FADB0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
