VALUES ('doc-09-mitre-attack-p0-17809', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-04T18:06:38.218Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Akira](https://attack.mitre.org/software/S1129) verifies the deletion of volume shadow copies by checking for the existence of the process ID related to the process created to delete these items.(Citation: Kersten Akira 2023)", "external_references": [{"description": "Max Kersten & Alexandre Mundo. (2023, November 29). Akira Ransomware. Retrieved April 4, 2024.", "source_name": "Kersten Akira 2023", "url": "https://www.trellix.com/blogs/research/akira-ransomware/"}], "id": "relationship--d33b14b1-7501-4bb3-af8c-3e2202fa572f", "modified": "2026-04-29T14:23:06.214Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6b2353-4b39-40ce-9d6d-d00b7a61e656", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17809', 0, 80, '09-mitre-attack', 'retrieved', '672D11DB3C6CB379711423A4ABB3B44A202CAB5D5157953E4BB8D7ABF7AA3B1A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
