VALUES ('doc-09-mitre-attack-p0-17812', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-14T21:29:34.302Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) tries to elevate privileges to SYSTEM using PsExec to locally execute as a service, such as cmd /c c:\\temp\\PsExec.exe -accepteula -j -d -s [Target Binary] .(Citation: Trellix Darkgate 2023)", "external_references": [{"description": "Ernesto Fernández Provecho, Pham Duy Phuc, Ciana Driscoll & Vinoo Thomas. (2023, November 21). The Continued Evolution of the DarkGate Malware-as-a-Service. Retrieved February 9, 2024.", "source_name": "Trellix Darkgate 2023", "url": "https://www.trellix.com/blogs/research/the-continued-evolution-of-the-darkgate-malware-as-a-service/"}], "id": "relationship--08a0175a-eb34-4ed2-a9ca-d458da65326a", "modified": "2026-04-29T14:23:05.915Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17812', 0, 92, '09-mitre-attack', 'retrieved', '17612B2AAD80A04D8BDAC5973DFE65D513806B1083C6A0AD793624B0BBA7607F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
