VALUES ('doc-09-mitre-attack-p0-17823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-21T03:02:05.495Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) uses the Delphi methods Sysutils::DiskSize and GlobalMemoryStatusEx to collect disk size and physical memory as part of the malware''s anti-analysis checks for running in a virtualized environment.(Citation: Ensilo Darkgate 2018) ", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}], "id": "relationship--350b8d90-f1ab-4bdf-a47e-8413751ed56c", "modified": "2026-04-29T14:23:05.990Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--f2514ae4-4e9b-4f26-a5ba-c4ae85fe93c3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17823', 0, 91, '09-mitre-attack', 'retrieved', 'EFAF4FDECF13D5507EB84ADBC5EE081F3B241D9A9F2D31B9F4816D2928CE9861', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
