VALUES ('doc-09-mitre-attack-p0-17824', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-12T20:33:51.007Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) will search for cryptocurrency wallets by examining application window names for specific strings.(Citation: Ensilo Darkgate 2018) [DarkGate](https://attack.mitre.org/software/S1111) extracts information collected via NirSoft tools from the hosting process''s memory by first identifying the window through the FindWindow API function.(Citation: Ensilo Darkgate 2018)", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}], "id": "relationship--36a93ca6-ad3b-468a-b5a3-d4676410ae1b", "modified": "2026-04-29T14:23:05.994Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--4ae4f953-fe58-4cc8-a327-33257e30a830", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17824', 0, 101, '09-mitre-attack', 'retrieved', 'FC874D7B1F95B32D926AB33905794DAAA060AA89C4E5D104F3BDD5DB0E3C59F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
