VALUES ('doc-09-mitre-attack-p0-17833', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-14T21:26:11.194Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) uses a hard-coded string as a seed, along with the victim machine hardware identifier and input text, to generate a unique string used as an internal mutex value to evade static detection based on mutexes.(Citation: Trellix Darkgate 2023)", "external_references": [{"description": "Ernesto Fernández Provecho, Pham Duy Phuc, Ciana Driscoll & Vinoo Thomas. (2023, November 21). The Continued Evolution of the DarkGate Malware-as-a-Service. Retrieved February 9, 2024.", "source_name": "Trellix Darkgate 2023", "url": "https://www.trellix.com/blogs/research/the-continued-evolution-of-the-darkgate-malware-as-a-service/"}], "id": "relationship--624b57dc-3cae-45c7-8473-c5116df57697", "modified": "2026-04-29T14:23:06.059Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17833', 0, 101, '09-mitre-attack', 'retrieved', '7C09F502D9BDD34BD91AF00D91C17C08FAA0AE6EFACA6359FCA6AE9F692F6C48', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
