INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-17847', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-14T20:57:47.723Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) uses the native Windows API CallWindowProc() to decode and launch encoded shellcode payloads during execution.(Citation: Trellix Darkgate 2023) [DarkGate](https://attack.mitre.org/software/S1111) can call kernel mode functions directly to hide the use of process hollowing methods during execution.(Citation: Ensilo Darkgate 2018) [DarkGate](https://attack.mitre.org/software/S1111) has also used the `CreateToolhelp32Snapshot`, `GetFileAttributesA` and `CreateProcessA` functions to obtain a list of running processes, to check for security products and to execute its malware.(Citation: Rapid7 BlackBasta 2024) ", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}, {"description": "Ernesto Fernández Provecho, Pham Duy Phuc, Ciana Driscoll & Vinoo Thomas. (2023, November 21). The Continued Evolution of the DarkGate Malware-as-a-Service. Retrieved February 9, 2024.", "source_name": "Trellix Darkgate 2023", "url": "https://www.trellix.com/blogs/research/the-continued-evolution-of-the-darkgate-malware-as-a-service/"}, {"description": "McGraw, T. (2024, December 4). Black Basta Ransomware Campaign Drops Zbot, DarkGate, and Custom Malware. Retrieved December 9, 2024.", "source_name": "Rapid7 BlackBasta 2024", "url": "https://www.rapid7.com/blog/post/2024/12/04/black-basta-ransomware-campaign-drops-zbot-darkgate-and-custom-malware/"}], "id": "relationship--a5252967-35e1-426a-8e92-ee066b7abcfc", "modified": "2026-04-29T14:23:06.150Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17847', 0, 187, '09-mitre-attack', 'retrieved', '7BAF94C253ED478B9C554A5307BBA53593EB07E9DCA460E2E7AAE02DCCD8E2F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
