VALUES ('doc-09-mitre-attack-p0-17858', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-07T00:11:40.593Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) attempts to steal Opera cookies, if present, after terminating the related process.(Citation: Rapid7 BlackBasta 2024) ", "external_references": [{"description": "McGraw, T. (2024, December 4). Black Basta Ransomware Campaign Drops Zbot, DarkGate, and Custom Malware. Retrieved December 9, 2024.", "source_name": "Rapid7 BlackBasta 2024", "url": "https://www.rapid7.com/blog/post/2024/12/04/black-basta-ransomware-campaign-drops-zbot-darkgate-and-custom-malware/"}], "id": "relationship--c54f50fe-017e-4015-8277-4d50f3ed0d97", "modified": "2026-04-29T14:23:06.195Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--10ffac09-e42d-4f56-ab20-db94c67d76ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17858', 0, 73, '09-mitre-attack', 'retrieved', '2247277D9FA1FCA85CAE3B57030FA8AB21E231A81A00E392A2269B1F410F0D10', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
