VALUES ('doc-09-mitre-attack-p0-17859', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-02T14:51:49.354Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) elevates accounts created through the malware to the local administration group during execution.(Citation: Ensilo Darkgate 2018)", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}], "id": "relationship--c6c84e61-787e-4a35-af35-57db72261547", "modified": "2026-04-29T14:23:06.197Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--3e6831b2-bf4c-4ae6-b328-2e7c6633b291", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17859', 0, 76, '09-mitre-attack', 'retrieved', '5DC51118A63F2C0D602EF6041B03702403B43ED1752E6E9BD835A18223FDA4C5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
