VALUES ('doc-09-mitre-attack-p0-17861', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-12T20:12:20.569Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) initial installation involves dropping several files to a hidden directory named after the victim machine name.(Citation: Ensilo Darkgate 2018) Additionally, [DarkGate](https://attack.mitre.org/software/S1111) uses [attrib](https://attack.mitre.org/software/S1176) to hide a directory in the following command: ` C:\\Windows\\system32\\attrib.exe” +h C:/rjtu/`.(Citation: gbhackers Darkgate Malware 2024)", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}, {"description": "Divya. (2024, April 30). Darkgate Malware Leveraging Autohotkey Following Teams. Retrieved November 22, 2024.", "source_name": "gbhackers Darkgate Malware 2024", "url": "https://gbhackers.com/darkgate-malware-leveraging/"}], "id": "relationship--d2010d54-21e6-4312-b197-bca1a4c07b86", "modified": "2026-04-29T14:23:06.213Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17861', 0, 121, '09-mitre-attack', 'retrieved', 'CA2D9FC2857791AA1B6590F693330DD6DC68C9B2AB3440F36ECDB1A289D55C03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
