VALUES ('doc-09-mitre-attack-p0-17865', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-07T00:01:46.109Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) has deleted all files in the Mozilla directory using the following command: `/c del /q /f /s C:\\Users\\User\\AppData\\Roaming\\Mozilla\\firefox*`.(Citation: Rapid7 BlackBasta 2024) ", "external_references": [{"description": "McGraw, T. (2024, December 4). Black Basta Ransomware Campaign Drops Zbot, DarkGate, and Custom Malware. Retrieved December 9, 2024.", "source_name": "Rapid7 BlackBasta 2024", "url": "https://www.rapid7.com/blog/post/2024/12/04/black-basta-ransomware-campaign-drops-zbot-darkgate-and-custom-malware/"}], "id": "relationship--eefb1822-dbcc-4919-8c76-f5ca0c371bf0", "modified": "2026-04-29T14:23:06.250Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--fb640c43-aa6b-431e-a961-a279010424ac", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17865', 0, 79, '09-mitre-attack', 'retrieved', 'C9FBADBD0D13DCC5FD780B53E914020700762BE7FB12AB6B3148FC3D32D38436', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
