VALUES ('doc-09-mitre-attack-p0-17867', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-12T19:58:46.076Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) leverages process hollowing techniques to evade detection, such as decrypting the content of an encrypted PE file and injecting it into the process vbc.exe.(Citation: Ensilo Darkgate 2018)(Citation: Rapid7 BlackBasta 2024)", "external_references": [{"description": "Adi Zeligson & Rotem Kerner. (2018, November 13). Enter The DarkGate - New Cryptocurrency Mining and Ransomware Campaign. Retrieved February 9, 2024.", "source_name": "Ensilo Darkgate 2018", "url": "https://www.fortinet.com/blog/threat-research/enter-the-darkgate-new-cryptocurrency-mining-and-ransomware-campaign"}, {"description": "McGraw, T. (2024, December 4). Black Basta Ransomware Campaign Drops Zbot, DarkGate, and Custom Malware. Retrieved December 9, 2024.", "source_name": "Rapid7 BlackBasta 2024", "url": "https://www.rapid7.com/blog/post/2024/12/04/black-basta-ransomware-campaign-drops-zbot-darkgate-and-custom-malware/"}], "id": "relationship--fd507797-cc28-4271-9a4c-d1fbe726722b", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--b200542e-e877-4395-875b-cf1a44537ca4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17867', 0, 116, '09-mitre-attack', 'retrieved', 'DF9FC957F481877E16C1BB7477BE892A92729B1A7F6FFB153B271589C31AA2F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}'