VALUES ('doc-09-mitre-attack-p0-17868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-14T20:36:15.930Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[DarkGate](https://attack.mitre.org/software/S1111) uses a malicious Windows Batch script to run the Windows code utility to retrieve follow-on script payloads.(Citation: Trellix Darkgate 2023) [DarkGate](https://attack.mitre.org/software/S1111) has also used `cmd.exe` to create a remote shell.(Citation: Rapid7 BlackBasta 2024) ", "external_references": [{"description": "Ernesto Fernández Provecho, Pham Duy Phuc, Ciana Driscoll & Vinoo Thomas. (2023, November 21). The Continued Evolution of the DarkGate Malware-as-a-Service. Retrieved February 9, 2024.", "source_name": "Trellix Darkgate 2023", "url": "https://www.trellix.com/blogs/research/the-continued-evolution-of-the-darkgate-malware-as-a-service/"}, {"description": "McGraw, T. (2024, December 4). Black Basta Ransomware Campaign Drops Zbot, DarkGate, and Custom Malware. Retrieved December 9, 2024.", "source_name": "Rapid7 BlackBasta 2024", "url": "https://www.rapid7.com/blog/post/2024/12/04/black-basta-ransomware-campaign-drops-zbot-darkgate-and-custom-malware/"}], "id": "relationship--ffc94259-697d-49f2-8713-6f4593d2e5ed", "modified": "2026-04-29T14:23:06.272Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--6f6f67c9-556d-4459-95c2-78d272190e52", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17868', 0, 123, '09-mitre-attack', 'retrieved', 'EEBE2BEC5BBA9171DAA3CAD202C53A4D484BAF0B442C27783E83CB0C5C77CD06', 'v1', '{"source_id": "09-mitre-attack", "version": "re