VALUES ('doc-09-mitre-attack-p0-17901', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-06T20:23:14.276Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LockBit 3.0](https://attack.mitre.org/software/S1202) can change the Registry values for Group Policy refresh time, to disable SmartScreen, and to disable Windows Defender.(Citation: Joint Cybersecurity Advisory LockBit 3.0 MAR 2023)(Citation: INCIBE-CERT LockBit MAR 2024)\n\n", "external_references": [{"description": "FBI et al. (2023, March 16). #StopRansomware: LockBit 3.0. Retrieved February 5, 2025.", "source_name": "Joint Cybersecurity Advisory LockBit 3.0 MAR 2023", "url": "https://www.cisa.gov/sites/default/files/2023-03/aa23-075a-stop-ransomware-lockbit.pdf"}, {"description": "INCIBE-CERT. (2024, March 14). LockBit: response and recovery actions. Retrieved February 5, 2025.", "source_name": "INCIBE-CERT LockBit MAR 2024", "url": "https://www.incibe.es/en/incibe-cert/blog/lockbit-response-and-recovery-actions"}], "id": "relationship--1c4a31d0-3567-4081-93f5-14de47eabecf", "modified": "2026-04-29T14:23:05.943Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--71fe9df1-1c6f-430c-ab9b-ff3c11074e52", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17901', 0, 106, '09-mitre-attack', 'retrieved', 'FAC350A9669F52955EE76A9158BCFDA8DBE0918135ED48372A57C9D201DA3E34', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
