VALUES ('doc-09-mitre-attack-p0-17956', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-21T23:40:08.238Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) hides a copy of itself in the user''s ~/Library directory by using a . at the beginning of the file name followed by 9 random characters.(Citation: wardle evilquest parti)", "external_references": [{"description": "Patrick Wardle. (2020, June 29). OSX.EvilQuest Uncovered part i: infection, persistence, and more!. Retrieved March 18, 2021.", "source_name": "wardle evilquest parti", "url": "https://objective-see.com/blog/blog_0x59.html"}], "id": "relationship--4306857b-542d-4a54-8b4d-b835e52c5c15", "modified": "2026-04-29T14:23:06.017Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17956', 0, 84, '09-mitre-attack', 'retrieved', 'A7F71C234A0470AF0DCFB71E9F671F252F6BA0BFF168DECA6680292AA826AE9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
