VALUES ('doc-09-mitre-attack-p0-17957', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-19T16:26:04.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) uses the CGEventTap functions to perform keylogging.(Citation: Trendmicro Evolving ThiefQuest 2020)", "external_references": [{"description": "Gabrielle Joyce Mabutas, Luis Magisa, Steven Du. (2020, July 17). Updates on Quickly-Evolving ThiefQuest macOS Malware. Retrieved April 26, 2021.", "source_name": "Trendmicro Evolving ThiefQuest 2020", "url": "https://www.trendmicro.com/en_us/research/20/g/updates-on-quickly-evolving-thiefquest-macos-malware.html"}], "id": "relationship--438f9fb0-bf82-4c72-8fdf-0dbc39bcf4fc", "modified": "2026-04-29T14:23:06.017Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--09a60ea3-a8d1-4ae5-976e-5783248b72a4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17957', 0, 70, '09-mitre-attack', 'retrieved', '6BCB48AFA8FA59FFC10A0BFA777E1E431AB48838CB0A32F1B755E9E65C8B1CEE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
