INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-17959', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-22T02:08:48.949Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) searches through the /Users/ folder looking for executable files. For each executable, [ThiefQuest](https://attack.mitre.org/software/S0595) prepends a copy of itself to the beginning of the file. When the file is executed, the [ThiefQuest](https://attack.mitre.org/software/S0595) code is executed first. [ThiefQuest](https://attack.mitre.org/software/S0595) creates a hidden file, copies the original target executable to the file, then executes the new hidden file to maintain the appearance of normal behavior. (Citation: wardle evilquest partii)(Citation: reed thiefquest ransomware analysis)", "external_references": [{"description": "Patrick Wardle. (2020, July 3). OSX.EvilQuest Uncovered part ii: insidious capabilities. Retrieved March 21, 2021.", "source_name": "wardle evilquest partii", "url": "https://objective-see.com/blog/blog_0x60.html"}, {"description": "Thomas Reed. (2020, July 7). Mac ThiefQuest malware may not be ransomware after all. Retrieved March 22, 2021.", "source_name": "reed thiefquest ransomware analysis", "url": "https://blog.malwarebytes.com/mac/2020/07/mac-thiefquest-malware-may-not-be-ransomware-after-all/"}], "id": "relationship--7300af33-a55d-47a7-86a6-3b756abfc8e5", "modified": "2026-04-29T14:23:06.082Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--960c3c86-1480-4d72-b4e0-8c242e84a5c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17959', 0, 148, '09-mitre-attack', 'retrieved', 'C9C14437FD05C67342FC7E6EE8E67A8366763EB5EA15B813BBE1242912176A04', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
