VALUES ('doc-09-mitre-attack-p0-17961', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-22T22:41:01.663Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) prepends a copy of itself to the beginning of an executable file while maintaining the name of the executable.(Citation: wardle evilquest partii)(Citation: reed thiefquest ransomware analysis)", "external_references": [{"description": "Patrick Wardle. (2020, July 3). OSX.EvilQuest Uncovered part ii: insidious capabilities. Retrieved March 21, 2021.", "source_name": "wardle evilquest partii", "url": "https://objective-see.com/blog/blog_0x60.html"}, {"description": "Thomas Reed. (2020, July 7). Mac ThiefQuest malware may not be ransomware after all. Retrieved March 22, 2021.", "source_name": "reed thiefquest ransomware analysis", "url": "https://blog.malwarebytes.com/mac/2020/07/mac-thiefquest-malware-may-not-be-ransomware-after-all/"}], "id": "relationship--75155c7f-3804-4f83-bbcb-4f654a5182e5", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17961', 0, 105, '09-mitre-attack', 'retrieved', 'EACE06730CF74D3371A3E8F3E5E31AE69F8DF238BA95A4690E64B5FEA1EBA43C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
