VALUES ('doc-09-mitre-attack-p0-17965', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-19T16:26:04.440Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) obtains a list of running processes using the function kill_unwanted .(Citation: wardle evilquest parti)", "external_references": [{"description": "Patrick Wardle. (2020, June 29). OSX.EvilQuest Uncovered part i: infection, persistence, and more!. Retrieved March 18, 2021.", "source_name": "wardle evilquest parti", "url": "https://objective-see.com/blog/blog_0x59.html"}], "id": "relationship--c85af3d4-ab10-4c49-91c4-bff9054096b8", "modified": "2026-04-29T14:23:06.199Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17965', 0, 69, '09-mitre-attack', 'retrieved', '59E825CFBEF69E0D44E83000E37897493AE3AF03C2C37DB577542303B01B2D96', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
