VALUES ('doc-09-mitre-attack-p0-17968', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-05T01:45:52.817Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) uses various API to perform behaviors such as executing payloads and performing local enumeration.(Citation: wardle evilquest partii)", "external_references": [{"description": "Patrick Wardle. (2020, July 3). OSX.EvilQuest Uncovered part ii: insidious capabilities. Retrieved March 21, 2021.", "source_name": "wardle evilquest partii", "url": "https://objective-see.com/blog/blog_0x60.html"}], "id": "relationship--dde881dc-6ad3-4819-b339-8019074818c7", "modified": "2026-04-29T14:23:06.228Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17968', 0, 70, '09-mitre-attack', 'retrieved', '0F37122D11DBFFE41339BB7560FAA5BAC869D579018638F6E54695F72F7AF597', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
