INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-17970', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-22T21:57:48.752Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[ThiefQuest](https://attack.mitre.org/software/S0595) uses a function named is_debugging to perform anti-debugging logic. The function invokes sysctl checking the returned value of P_TRACED . [ThiefQuest](https://attack.mitre.org/software/S0595) also calls ptrace with the PTRACE_DENY_ATTACH flag to prevent debugging.(Citation: wardle evilquest partii)", "external_references": [{"description": "Patrick Wardle. (2020, July 3). OSX.EvilQuest Uncovered part ii: insidious capabilities. Retrieved March 21, 2021.", "source_name": "wardle evilquest partii", "url": "https://objective-see.com/blog/blog_0x60.html"}], "id": "relationship--e711d51c-94d3-4a20-ae11-d3584bae36d9", "modified": "2026-04-29T14:23:06.239Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--727afb95-3d0f-4451-b297-362a43909923", "spec_version": "2.1", "target_ref": "attack-pattern--e4dc8c01-417f-458d-9ee0-bb0617c1b391", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17970', 0, 87, '09-mitre-attack', 'retrieved', 'E6C53AFD6C5D76D5B410310A98972E5086D7AD48773738ACD91AA00521ECE353', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
