VALUES ('doc-09-mitre-attack-p0-17973', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-16T15:32:34.178Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FoggyWeb](https://attack.mitre.org/software/S0661) can use a dynamic XOR key and a custom XOR methodology to encode data before exfiltration. Also, [FoggyWeb](https://attack.mitre.org/software/S0661) can encode C2 command output within a legitimate WebP file.(Citation: MSTIC FoggyWeb September 2021)", "external_references": [{"description": "Ramin Nafisi. (2021, September 27). FoggyWeb: Targeted NOBELIUM malware leads to persistent backdoor. Retrieved October 4, 2021.", "source_name": "MSTIC FoggyWeb September 2021", "url": "https://www.microsoft.com/security/blog/2021/09/27/foggyweb-targeted-nobelium-malware-leads-to-persistent-backdoor/"}], "id": "relationship--2a9fde8d-dbec-42e9-ad73-02f80e765a91", "modified": "2026-04-29T14:23:05.963Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72911fe3-f085-40f7-b4f2-f25a4221fe44", "spec_version": "2.1", "target_ref": "attack-pattern--143c0cbb-a297-4142-9624-87ffc778980b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17973', 0, 88, '09-mitre-attack', 'retrieved', '0CED470CCF799290CE5F144E1FFFAB39AE6AB2FFE1E1A4151AE1D7E7E2C063B0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
