VALUES ('doc-09-mitre-attack-p0-17981', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-15T18:32:24.932Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FoggyWeb](https://attack.mitre.org/software/S0661)''s loader can enumerate all Common Language Runtimes (CLRs) and running Application Domains in the compromised AD FS server''s Microsoft.IdentityServer.ServiceHost.exe process.(Citation: MSTIC FoggyWeb September 2021)", "external_references": [{"description": "Ramin Nafisi. (2021, September 27). FoggyWeb: Targeted NOBELIUM malware leads to persistent backdoor. Retrieved October 4, 2021.", "source_name": "MSTIC FoggyWeb September 2021", "url": "https://www.microsoft.com/security/blog/2021/09/27/foggyweb-targeted-nobelium-malware-leads-to-persistent-backdoor/"}], "id": "relationship--6d91c756-df9c-4fbe-9489-2cf6cf7ba206", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72911fe3-f085-40f7-b4f2-f25a4221fe44", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17981', 0, 80, '09-mitre-attack', 'retrieved', '2D1BB08544AF8857CA2353C0B4A56A2A5CB0AC5C7B882F4BAF67B159873E0073', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
