VALUES ('doc-09-mitre-attack-p0-17985', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-16T15:32:34.286Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FoggyWeb](https://attack.mitre.org/software/S0661) can configure custom listeners to passively monitor all incoming HTTP GET and POST requests sent to the AD FS server from the intranet/internet and intercept HTTP requests that match the custom URI patterns defined by the actor.(Citation: MSTIC FoggyWeb September 2021)", "external_references": [{"description": "Ramin Nafisi. (2021, September 27). FoggyWeb: Targeted NOBELIUM malware leads to persistent backdoor. Retrieved October 4, 2021.", "source_name": "MSTIC FoggyWeb September 2021", "url": "https://www.microsoft.com/security/blog/2021/09/27/foggyweb-targeted-nobelium-malware-leads-to-persistent-backdoor/"}], "id": "relationship--98b8b974-ac4f-4286-b657-f34f813c1d12", "modified": "2026-04-29T14:23:06.133Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72911fe3-f085-40f7-b4f2-f25a4221fe44", "spec_version": "2.1", "target_ref": "attack-pattern--3257eb21-f9a7-4430-8de1-d8b6e288f529", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17985', 0, 97, '09-mitre-attack', 'retrieved', '96C6498FD20DA2D812C293FA7C023D147999D4E088D72F381DD59934D87B52A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
