VALUES ('doc-09-mitre-attack-p0-17988', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-11-16T15:32:34.259Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FoggyWeb](https://attack.mitre.org/software/S0661)''s loader has used DLL Search Order Hijacking to load malicious code instead of the legitimate `version.dll` during the `Microsoft.IdentityServer.ServiceHost.exe` execution process.(Citation: MSTIC FoggyWeb September 2021)", "external_references": [{"description": "Ramin Nafisi. (2021, September 27). FoggyWeb: Targeted NOBELIUM malware leads to persistent backdoor. Retrieved October 4, 2021.", "source_name": "MSTIC FoggyWeb September 2021", "url": "https://www.microsoft.com/security/blog/2021/09/27/foggyweb-targeted-nobelium-malware-leads-to-persistent-backdoor/"}], "id": "relationship--9d7577f9-2003-4cbc-b7cb-58f2dc20714c", "modified": "2026-04-29T14:23:06.140Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72911fe3-f085-40f7-b4f2-f25a4221fe44", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17988', 0, 81, '09-mitre-attack', 'retrieved', 'EF5EF7D5CD361FB1229D725F19DEAD2424DD6AD58544BD1C03E10112B31B8F75', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
