VALUES ('doc-09-mitre-attack-p0-17994', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-12T10:58:01.612Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NGLite](https://attack.mitre.org/software/S1106) will run the whoami command to gather system information and return this to the command and control server.(Citation: NGLite Trojan)", "external_references": [{"description": "Robert Falcone, Jeff White, and Peter Renals. (2021, November 7). Targeted Attack Campaign Against ManageEngine ADSelfService Plus Delivers Godzilla Webshells, NGLite Trojan and KdcSponge Stealer. Retrieved February 8, 2024.", "source_name": "NGLite Trojan", "url": "https://unit42.paloaltonetworks.com/manageengine-godzilla-nglite-kdcsponge/"}], "id": "relationship--8a0ac9c9-e8e2-44a2-b2b0-87b4b4fa90fb", "modified": "2026-04-29T14:23:06.113Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72b5f07f-5448-4e00-9ff2-08bc193a7b77", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17994', 0, 86, '09-mitre-attack', 'retrieved', 'AAAEB0DD871CD1E127F97560C3E9D747BF298548F2C0B2C87190D16C88C4791F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
