VALUES ('doc-09-mitre-attack-p0-17997', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-12T10:51:54.129Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NGLite](https://attack.mitre.org/software/S1106) identifies the victim system MAC and IPv4 addresses and uses these to establish a victim identifier.(Citation: NGLite Trojan)", "external_references": [{"description": "Robert Falcone, Jeff White, and Peter Renals. (2021, November 7). Targeted Attack Campaign Against ManageEngine ADSelfService Plus Delivers Godzilla Webshells, NGLite Trojan and KdcSponge Stealer. Retrieved February 8, 2024.", "source_name": "NGLite Trojan", "url": "https://unit42.paloaltonetworks.com/manageengine-godzilla-nglite-kdcsponge/"}], "id": "relationship--cad1f2d3-c3c2-4f55-863e-0de712cd84b7", "modified": "2026-04-29T14:23:06.202Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--72b5f07f-5448-4e00-9ff2-08bc193a7b77", "spec_version": "2.1", "target_ref": "attack-pattern--707399d6-ab3e-4963-9315-d9d3818cd6a0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-17997', 0, 84, '09-mitre-attack', 'retrieved', '3213DE4A3FDA5A849923086CB1D320016804FDC6C0635D2DDC5B24B5C2769E52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
