VALUES ('doc-09-mitre-attack-p0-18023', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hydraq](https://attack.mitre.org/software/S0203) creates a backdoor through which remote attackers can retrieve system information, such as CPU speed, from Registry keys.(Citation: Symantec Trojan.Hydraq Jan 2010)(Citation: Symantec Hydraq Jan 2010)", "external_references": [{"description": "Symantec Security Response. (2010, January 18). The Trojan.Hydraq Incident. Retrieved February 20, 2018.", "source_name": "Symantec Trojan.Hydraq Jan 2010", "url": "https://www.symantec.com/connect/blogs/trojanhydraq-incident"}, {"description": "Lelli, A. (2010, January 11). Trojan.Hydraq. Retrieved February 20, 2018.", "source_name": "Symantec Hydraq Jan 2010", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2010-011114-1830-99"}], "id": "relationship--0825b101-deff-45cf-867c-af3ccb233744", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--73a4793a-ce55-4159-b2a6-208ef29b326f", "spec_version": "2.1", "target_ref": "attack-pattern--c32f7008-9fea-41f7-8366-5eb9b74bd896", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18023', 0, 96, '09-mitre-attack', 'retrieved', 'F6F7C159F03458F22DA2D64C58AD2F9A98DBD4DBF16A66A85BDE43CA760DF256', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
