VALUES ('doc-09-mitre-attack-p0-18027', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hydraq](https://attack.mitre.org/software/S0203) creates a backdoor through which remote attackers can retrieve information such as computer name, OS version, processor speed, memory size, and CPU speed.(Citation: Symantec Hydraq Jan 2010)", "external_references": [{"description": "Lelli, A. (2010, January 11). Trojan.Hydraq. Retrieved February 20, 2018.", "source_name": "Symantec Hydraq Jan 2010", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2010-011114-1830-99"}], "id": "relationship--4be87979-faf9-4a7a-998a-d1aa3fbf5a80", "modified": "2026-04-29T14:23:06.029Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--73a4793a-ce55-4159-b2a6-208ef29b326f", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18027', 0, 76, '09-mitre-attack', 'retrieved', '9FF5C0E02D5BC41931619B03B4A7853A3A8E2FC31DC3DFB1188AA23228E9AAA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
