VALUES ('doc-09-mitre-attack-p0-18029', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Hydraq](https://attack.mitre.org/software/S0203) creates a Registry subkey to register its created service, and can also uninstall itself later by deleting this value. [Hydraq](https://attack.mitre.org/software/S0203)''s backdoor also enables remote attackers to modify and delete subkeys.(Citation: Symantec Trojan.Hydraq Jan 2010)(Citation: Symantec Hydraq Jan 2010)", "external_references": [{"description": "Symantec Security Response. (2010, January 18). The Trojan.Hydraq Incident. Retrieved February 20, 2018.", "source_name": "Symantec Trojan.Hydraq Jan 2010", "url": "https://www.symantec.com/connect/blogs/trojanhydraq-incident"}, {"description": "Lelli, A. (2010, January 11). Trojan.Hydraq. Retrieved February 20, 2018.", "source_name": "Symantec Hydraq Jan 2010", "url": "https://www.symantec.com/security_response/writeup.jsp?docid=2010-011114-1830-99"}], "id": "relationship--541855dd-0249-4f63-8e95-0024f760484e", "modified": "2026-04-29T14:23:06.040Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--73a4793a-ce55-4159-b2a6-208ef29b326f", "spec_version": "2.1", "target_ref": "attack-pattern--57340c81-c025-4189-8fa0-fc7ede51bae4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18029', 0, 108, '09-mitre-attack', 'retrieved', '44AC6C33DB8E6C106D5F7F8EFAB409C3213969B40851FA0E1CA440706564395A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
