VALUES ('doc-09-mitre-attack-p0-18086', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-27T22:05:32.039Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Operators deploying [Netwalker](https://attack.mitre.org/software/S0457) have used psexec to copy the [Netwalker](https://attack.mitre.org/software/S0457) payload across accessible systems.(Citation: Sophos Netwalker May 2020)", "external_references": [{"description": "Szappanos, G., Brandt, A.. (2020, May 27). Netwalker ransomware tools give insight into threat actor. Retrieved May 27, 2020.", "source_name": "Sophos Netwalker May 2020", "url": "https://news.sophos.com/en-us/2020/05/27/netwalker-ransomware-tools-give-insight-into-threat-actor/"}], "id": "relationship--2dd1c028-bebc-4631-b17b-3dd27a595c00", "modified": "2026-04-29T14:23:05.967Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--754effde-613c-4244-a83e-fb659b2a4d06", "spec_version": "2.1", "target_ref": "attack-pattern--bf90d72c-c00b-45e3-b3aa-68560560d4c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18086', 0, 75, '09-mitre-attack', 'retrieved', 'F4532A51CC689E9C10EE08010399C426645C107E892E747B466B76ACD7D69D38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
