VALUES ('doc-09-mitre-attack-p0-18088', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-27T22:05:32.076Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Operators deploying [Netwalker](https://attack.mitre.org/software/S0457) have used batch scripts to retrieve the [Netwalker](https://attack.mitre.org/software/S0457) payload.(Citation: Sophos Netwalker May 2020)", "external_references": [{"description": "Szappanos, G., Brandt, A.. (2020, May 27). Netwalker ransomware tools give insight into threat actor. Retrieved May 27, 2020.", "source_name": "Sophos Netwalker May 2020", "url": "https://news.sophos.com/en-us/2020/05/27/netwalker-ransomware-tools-give-insight-into-threat-actor/"}], "id": "relationship--5ff771c3-7d1c-4d04-a81e-76e374951e72", "modified": "2026-04-29T14:23:06.056Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--754effde-613c-4244-a83e-fb659b2a4d06", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18088', 0, 73, '09-mitre-attack', 'retrieved', '7C883100EE1D4A25A5AFAC1BDAA44D3BA068C2B223AA1F9458196CE0E62C8F3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
