VALUES ('doc-09-mitre-attack-p0-18130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-21T17:14:56.863Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[USBferry](https://attack.mitre.org/software/S0452) can use netstat and nbtstat to detect active network connections.(Citation: TrendMicro Tropic Trooper May 2020)\t", "external_references": [{"description": "Chen, J.. (2020, May 12). Tropic Trooper’s Back: USBferry Attack Targets Air gapped Environments. Retrieved May 20, 2020.", "source_name": "TrendMicro Tropic Trooper May 2020", "url": "https://documents.trendmicro.com/assets/Tech-Brief-Tropic-Trooper-s-Back-USBferry-Attack-Targets-Air-gapped-Environments.pdf"}], "id": "relationship--e6cd4568-3c15-4d1d-ab2c-c799141cf34b", "modified": "2026-04-29T14:23:06.239Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--75bba379-4ba1-467e-8c60-ec2b269ee984", "spec_version": "2.1", "target_ref": "attack-pattern--7e150503-88e7-4861-866b-ff1ac82c4475", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18130', 0, 73, '09-mitre-attack', 'retrieved', '1FA17556875D2135058BEED752D8C1819F35BAB4216DD9D3245A210C9FC19E9B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
