VALUES ('doc-09-mitre-attack-p0-18139', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-12T12:52:29.307Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WannaCry](https://attack.mitre.org/software/S0366) uses [attrib](https://attack.mitre.org/software/S1176) +h to make some of its files hidden.(Citation: LogRhythm WannaCry)(Citation: Checkpoint WannaCry 2017)", "external_references": [{"description": "Noerenberg, E., Costis, A., and Quist, N. (2017, May 16). A Technical Analysis of WannaCry Ransomware. Retrieved December 8, 2024.", "source_name": "LogRhythm WannaCry", "url": "https://web.archive.org/web/20230522041200/https://logrhythm.com/blog/a-technical-analysis-of-wannacry-ransomware/"}, {"description": "Pal, P. (2017, May 16). CRYING IS FUTILE: SandBlast Forensic Analysis of WannaCry. Retrieved November 22, 2024.", "source_name": "Checkpoint WannaCry 2017", "url": "https://blog.checkpoint.com/research/crying-futile-sandblast-forensic-analysis-wannacry/"}], "id": "relationship--a802b910-b023-425a-8c09-c1b2df185812", "modified": "2026-04-29T14:23:06.154Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--75ecdbf1-c2bb-4afc-a3f9-c8da4de8c661", "spec_version": "2.1", "target_ref": "attack-pattern--ec8fc7e2-b356-455c-8db5-2e37be158e7d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18139', 0, 96, '09-mitre-attack', 'retrieved', '9BA44D55977D8731360CEB0C875E0816F9E6EF467D7299451BBFDC8B0100734B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
