VALUES ('doc-09-mitre-attack-p0-18144', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T13:38:24.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WannaCry](https://attack.mitre.org/software/S0366) creates the service \"mssecsvc2.0\" with the display name \"Microsoft Security Center (2.0) Service.\"(Citation: LogRhythm WannaCry)(Citation: FireEye WannaCry 2017)", "external_references": [{"description": "Berry, A., Homan, J., and Eitzman, R. (2017, May 23). WannaCry Malware Profile. Retrieved March 15, 2019.", "source_name": "FireEye WannaCry 2017", "url": "https://www.fireeye.com/blog/threat-research/2017/05/wannacry-malware-profile.html"}, {"description": "Noerenberg, E., Costis, A., and Quist, N. (2017, May 16). A Technical Analysis of WannaCry Ransomware. Retrieved December 8, 2024.", "source_name": "LogRhythm WannaCry", "url": "https://web.archive.org/web/20230522041200/https://logrhythm.com/blog/a-technical-analysis-of-wannacry-ransomware/"}], "id": "relationship--facd3eca-9156-47a8-85d1-09719bc0eb88", "modified": "2026-04-29T14:23:06.265Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--75ecdbf1-c2bb-4afc-a3f9-c8da4de8c661", "spec_version": "2.1", "target_ref": "attack-pattern--2959d63f-73fd-46a1-abd2-109d7dcede32", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18144', 0, 99, '09-mitre-attack', 'retrieved', '5D2C308833E27BD6A6FB3020A01077A100ABC13BBC0857AF0B554375BA36CF6A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
