VALUES ('doc-09-mitre-attack-p0-18145', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-03-26T13:38:24.627Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[WannaCry](https://attack.mitre.org/software/S0366) attempts to copy itself to remote computers after gaining access via an SMB exploit.(Citation: LogRhythm WannaCry)", "external_references": [{"description": "Noerenberg, E., Costis, A., and Quist, N. (2017, May 16). A Technical Analysis of WannaCry Ransomware. Retrieved December 8, 2024.", "source_name": "LogRhythm WannaCry", "url": "https://web.archive.org/web/20230522041200/https://logrhythm.com/blog/a-technical-analysis-of-wannacry-ransomware/"}], "id": "relationship--fe78de3a-107f-4870-b5a1-c60289d68dec", "modified": "2026-04-29T14:23:06.271Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--75ecdbf1-c2bb-4afc-a3f9-c8da4de8c661", "spec_version": "2.1", "target_ref": "attack-pattern--bf90d72c-c00b-45e3-b3aa-68560560d4c5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18145', 0, 73, '09-mitre-attack', 'retrieved', 'EE773E3D4C985037B6EFB25A2A250C6DA57053481674C1718B8436FAD7C4483E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
