VALUES ('doc-09-mitre-attack-p0-18159', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T16:13:52.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Gazer](https://attack.mitre.org/software/S0168) versions are signed with various valid certificates; one was likely faked and issued by Comodo for \"Solid Loop Ltd,\" and another was issued for \"Ultimate Computer Support Ltd.\"(Citation: ESET Gazer Aug 2017)(Citation: Securelist WhiteBear Aug 2017)", "external_references": [{"description": "ESET. (2017, August). Gazing at Gazer: Turla’s new second stage backdoor. Retrieved September 14, 2017.", "source_name": "ESET Gazer Aug 2017", "url": "https://www.welivesecurity.com/wp-content/uploads/2017/08/eset-gazer.pdf"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2017, August 30). Introducing WhiteBear. Retrieved September 21, 2017.", "source_name": "Securelist WhiteBear Aug 2017", "url": "https://securelist.com/introducing-whitebear/81638/"}], "id": "relationship--c354bbc0-74c4-4805-b6e6-f33f49272f86", "modified": "2026-04-29T14:23:06.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76abb3ef-dafd-4762-97cb-a35379429db4", "spec_version": "2.1", "target_ref": "attack-pattern--32901740-b42c-4fdd-bc02-345b5dc57082", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18159', 0, 114, '09-mitre-attack', 'retrieved', 'D8A0ECFC04C43102F4C50647B70CD9422AF4CC5D4C3D161A0E2B238A467E4433', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
