VALUES ('doc-09-mitre-attack-p0-18197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-18T17:48:07.901Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) has used JavaScript files as part its infection chain during malicious spam \n email campaigns.(Citation: Elastic Latrodectus May 2024)(Citation: Bitsight Latrodectus June 2024)(Citation: Palo Alto Latrodectus Activity June 2024)\n", "external_references": [{"description": "Batista, J. (2024, June 17). Latrodectus, are you coming back?. Retrieved September 13, 2024.", "source_name": "Bitsight Latrodectus June 2024", "url": "https://www.bitsight.com/blog/latrodectus-are-you-coming-back"}, {"description": "Stepanic, D. and Bousseaden, S. (2024, May 15). Spring Cleaning with LATRODECTUS: A Potential Replacement for ICEDID. Retrieved September 13, 2024.", "source_name": "Elastic Latrodectus May 2024", "url": "https://www.elastic.co/security-labs/spring-cleaning-with-latrodectus"}, {"description": "Unit 42. (2024, June 25). 2024-06-25-IOCs-from-Latrodectus-activity. Retrieved September 13, 2024.", "source_name": "Palo Alto Latrodectus Activity June 2024", "url": "https://github.com/PaloAltoNetworks/Unit42-timely-threat-intel/blob/main/2024-06-25-IOCs-from-Latrodectus-activity.txt"}], "id": "relationship--6d5e93c2-073a-4974-a25f-c5a805780a45", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18197', 0, 131, '09-mitre-attack', 'retrieved', 'D555