VALUES ('doc-09-mitre-attack-p0-18202', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-18T18:22:25.432Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) has used multiple Windows API post exploitation including `GetAdaptersInfo`, `CreateToolhelp32Snapshot`, and `CreateProcessW`.(Citation: Elastic Latrodectus May 2024)(Citation: Bitsight Latrodectus June 2024)", "external_references": [{"description": "Batista, J. (2024, June 17). Latrodectus, are you coming back?. Retrieved September 13, 2024.", "source_name": "Bitsight Latrodectus June 2024", "url": "https://www.bitsight.com/blog/latrodectus-are-you-coming-back"}, {"description": "Stepanic, D. and Bousseaden, S. (2024, May 15). Spring Cleaning with LATRODECTUS: A Potential Replacement for ICEDID. Retrieved September 13, 2024.", "source_name": "Elastic Latrodectus May 2024", "url": "https://www.elastic.co/security-labs/spring-cleaning-with-latrodectus"}], "id": "relationship--948eb193-9037-43cf-99db-5d7912277ed0", "modified": "2026-04-29T14:23:06.127Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18202', 0, 102, '09-mitre-attack', 'retrieved', 'D6618266EAC99FAF3933935FB9F13ADB2430443545ADCD9190FA1E70E6604C30', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
