VALUES ('doc-09-mitre-attack-p0-18215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-17T20:02:58.817Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) can determine if it is running in a virtualized environment by checking the OS version, checking the number of running processes, ensuring a 64-bit application is running on a 64-bit host, and checking if the host has a valid MAC address.(Citation: Latrodectus APR 2024)(Citation: Elastic Latrodectus May 2024)(Citation: Bitsight Latrodectus June 2024)", "external_references": [{"description": "Batista, J. (2024, June 17). Latrodectus, are you coming back?. Retrieved September 13, 2024.", "source_name": "Bitsight Latrodectus June 2024", "url": "https://www.bitsight.com/blog/latrodectus-are-you-coming-back"}, {"description": "Proofpoint Threat Research and Team Cymru S2 Threat Research. (2024, April 4). Latrodectus: This Spider Bytes Like Ice . Retrieved May 31, 2024.", "source_name": "Latrodectus APR 2024", "url": "https://www.proofpoint.com/us/blog/threat-insight/latrodectus-spider-bytes-ice"}, {"description": "Stepanic, D. and Bousseaden, S. (2024, May 15). Spring Cleaning with LATRODECTUS: A Potential Replacement for ICEDID. Retrieved September 13, 2024.", "source_name": "Elastic Latrodectus May 2024", "url": "https://www.elastic.co/security-labs/spring-cleaning-with-latrodectus"}], "id": "relationship--d80dc743-4799-4497-8708-b1324b38e3e1", "modified": "2026-04-29T14:23:06.220Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18215', 0, 164, '09-mitre-attack', 'retrieved', '3F6E66CC33345E4D380FB5AFBE64ABFF0FB7B760E8AD7B3DE3318AA180653CD7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
