VALUES ('doc-09-mitre-attack-p0-18216', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-17T17:17:03.153Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) has been distributed to victims through emails containing malicious links.(Citation: Latrodectus APR 2024)(Citation: Bleeping Computer Latrodectus April 2024)", "external_references": [{"description": "Abrams, L. (2024, April 30). New Latrodectus malware attacks use Microsoft, Cloudflare themes. Retrieved September 13, 2024.", "source_name": "Bleeping Computer Latrodectus April 2024", "url": "https://www.bleepingcomputer.com/news/security/new-latrodectus-malware-attacks-use-microsoft-cloudflare-themes/"}, {"description": "Proofpoint Threat Research and Team Cymru S2 Threat Research. (2024, April 4). Latrodectus: This Spider Bytes Like Ice . Retrieved May 31, 2024.", "source_name": "Latrodectus APR 2024", "url": "https://www.proofpoint.com/us/blog/threat-insight/latrodectus-spider-bytes-ice"}], "id": "relationship--d9a681a0-bf13-40b2-9534-f244d48d3a92", "modified": "2026-04-29T14:23:06.222Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--2b742742-28c3-4e1b-bab7-8350d6300fa7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18216', 0, 105, '09-mitre-attack', 'retrieved', 'F526A67BA816BA76B020DA937842C5FCB79F17CDB6393F8B8DCECB30608AD22B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
