VALUES ('doc-09-mitre-attack-p0-18217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-18T17:52:43.584Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) has used WMI in malicious email infection chains to facilitate the installation of remotely-hosted files.(Citation: Elastic Latrodectus May 2024)(Citation: Bitsight Latrodectus June 2024)", "external_references": [{"description": "Batista, J. (2024, June 17). Latrodectus, are you coming back?. Retrieved September 13, 2024.", "source_name": "Bitsight Latrodectus June 2024", "url": "https://www.bitsight.com/blog/latrodectus-are-you-coming-back"}, {"description": "Stepanic, D. and Bousseaden, S. (2024, May 15). Spring Cleaning with LATRODECTUS: A Potential Replacement for ICEDID. Retrieved September 13, 2024.", "source_name": "Elastic Latrodectus May 2024", "url": "https://www.elastic.co/security-labs/spring-cleaning-with-latrodectus"}], "id": "relationship--e7995f43-d3f1-4ad2-b3bd-fc835faa3333", "modified": "2026-04-29T14:23:06.240Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--01a5a209-b94c-450b-b7f9-946497d91055", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18217', 0, 105, '09-mitre-attack', 'retrieved', '68373438ADE98C912D8952971B6F88DA8E1BBB17F3BD16F5532AA9DCD2BDEDBC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
