VALUES ('doc-09-mitre-attack-p0-18219', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-18T19:15:14.228Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Latrodectus](https://attack.mitre.org/software/S1160) can run `C:\\Windows\\System32\\cmd.exe /c net group \"Domain Admins\" /domain` to identify domain administrator accounts.(Citation: Elastic Latrodectus May 2024)", "external_references": [{"description": "Stepanic, D. and Bousseaden, S. (2024, May 15). Spring Cleaning with LATRODECTUS: A Potential Replacement for ICEDID. Retrieved September 13, 2024.", "source_name": "Elastic Latrodectus May 2024", "url": "https://www.elastic.co/security-labs/spring-cleaning-with-latrodectus"}], "id": "relationship--f451a96a-9266-4252-bd1f-d61c12691708", "modified": "2026-04-29T14:23:06.257Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--76fde8df-3495-47c9-82eb-125c4f7fb621", "spec_version": "2.1", "target_ref": "attack-pattern--21875073-b0ee-49e3-9077-1e2a885359af", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18219', 0, 78, '09-mitre-attack', 'retrieved', '88943C7C0D934CC18ADF3B613A1583C1E22FF3A7FF9405369F58624D217CE933', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
