VALUES ('doc-09-mitre-attack-p0-18246', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-09T19:10:16.792Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Saint Bot](https://attack.mitre.org/software/S1018) loader has used API calls to spawn `MSBuild.exe` in a suspended state before injecting the decrypted [Saint Bot](https://attack.mitre.org/software/S1018) binary into it.(Citation: Palo Alto Unit 42 OutSteel SaintBot February 2022 )", "external_references": [{"description": "Unit 42. (2022, February 25). Spear Phishing Attacks Target Organizations in Ukraine, Payloads Include the Document Stealer OutSteel and the Downloader SaintBot. Retrieved June 9, 2022.", "source_name": "Palo Alto Unit 42 OutSteel SaintBot February 2022 ", "url": "https://unit42.paloaltonetworks.com/ukraine-targeted-outsteel-saintbot/"}], "id": "relationship--b58eb56c-9992-4fcd-ae4f-b7a1301667f0", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7724581b-06ff-4d2b-b77c-80dc8d53070b", "spec_version": "2.1", "target_ref": "attack-pattern--b200542e-e877-4395-875b-cf1a44537ca4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18246', 0, 102, '09-mitre-attack', 'retrieved', 'E900E4BECA10233734F33B1FDBC58670D19657E8D5AFEBAB56DE3FC73821CB97', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
