VALUES ('doc-09-mitre-attack-p0-18255', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-09T21:07:44.025Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Saint Bot](https://attack.mitre.org/software/S1018) has used Base64 to encode its C2 communications.(Citation: Malwarebytes Saint Bot April 2021)", "external_references": [{"description": "Hasherezade. (2021, April 6). A deep dive into Saint Bot, a new downloader. Retrieved June 9, 2022.", "source_name": "Malwarebytes Saint Bot April 2021", "url": "https://blog.malwarebytes.com/threat-intelligence/2021/04/a-deep-dive-into-saint-bot-downloader/"}], "id": "relationship--ee6e6954-706f-4b19-9081-f9603c3f9e3e", "modified": "2026-04-29T14:23:06.250Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7724581b-06ff-4d2b-b77c-80dc8d53070b", "spec_version": "2.1", "target_ref": "attack-pattern--04fd5427-79c7-44ea-ae13-11b24778ff1c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18255', 0, 71, '09-mitre-attack', 'retrieved', 'E4F326CC2348F43BCEE2E25CFEF63F1895D448BD65B351DC83B5835E280838A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
