VALUES ('doc-09-mitre-attack-p0-18355', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T17:53:10.599Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyViper](https://attack.mitre.org/software/S9032) has the ability to check for a specified list of security tools in the compromised environment.(Citation: ESET_MuddyWater_Dec2025) ", "external_references": [{"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}], "id": "relationship--1b19ae5d-f4c5-4962-a069-3d264ff1a80d", "modified": "2026-04-29T14:23:05.941Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7b92e996-b535-4159-be16-3c3aee4edf54", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18355', 0, 68, '09-mitre-attack', 'retrieved', '6832FFA60A8C3BC4BE69DD7818865F0AB616AD344F5C9DB3FF5F223977278B6C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
