VALUES ('doc-09-mitre-attack-p0-18357', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-20T18:10:49.899Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[MuddyViper](https://attack.mitre.org/software/S9032) has the ability to encrypt C2 communication using AES-CBC using the CNG API, the key `0608101047106453101617106423101013101012101083109710108585106969`, and the initialization vector `0`.(Citation: ESET_MuddyWater_Dec2025) ", "external_references": [{"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}], "id": "relationship--38848a62-c389-4344-8bed-094292cef803", "modified": "2026-04-29T14:23:05.997Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7b92e996-b535-4159-be16-3c3aee4edf54", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18357', 0, 73, '09-mitre-attack', 'retrieved', '2E3A9F8FDA820CAA03DEEFD8DE7491B920981F0F0790AC553A6C4B5CF499A5B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
