VALUES ('doc-09-mitre-attack-p0-18372', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T20:23:35.007Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[TYPEFRAME](https://attack.mitre.org/software/S0263) can install and store encrypted configuration data under the Registry key HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\ShellCompatibility\\Applications\\laxhost.dll and HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\PrintConfigs .(Citation: US-CERT TYPEFRAME June 2018)", "external_references": [{"description": "US-CERT. (2018, June 14). MAR-10135536-12 – North Korean Trojan: TYPEFRAME. Retrieved July 13, 2018.", "source_name": "US-CERT TYPEFRAME June 2018", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR18-165A"}], "id": "relationship--3a11bfd9-1c27-4f54-926d-883cfa9b69cd", "modified": "2026-04-29T14:23:05.999Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7ba0fc46-197d-466d-8b9f-f1c64d5d81e5", "spec_version": "2.1", "target_ref": "attack-pattern--02c5abff-30bf-4703-ab92-1f6072fae939", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18372', 0, 72, '09-mitre-attack', 'retrieved', '8D390D8D0FC9EA55A0DD7A39C00F7A1107F065F27FB23DC6639FABFBAEF25604', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
