VALUES ('doc-09-mitre-attack-p0-18376', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A Word document delivering [TYPEFRAME](https://attack.mitre.org/software/S0263) prompts the user to enable macro execution.(Citation: US-CERT TYPEFRAME June 2018)", "external_references": [{"description": "US-CERT. (2018, June 14). MAR-10135536-12 – North Korean Trojan: TYPEFRAME. Retrieved July 13, 2018.", "source_name": "US-CERT TYPEFRAME June 2018", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR18-165A"}], "id": "relationship--6d8d9425-86ec-42d3-bce5-2af53d4f1fad", "modified": "2026-04-29T14:23:06.074Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7ba0fc46-197d-466d-8b9f-f1c64d5d81e5", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18376', 0, 68, '09-mitre-attack', 'retrieved', '323783E7A13E4AD10E7598DD0E9081C2807DE6288F716206EF5BDAAABFBE9F66', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
