VALUES ('doc-09-mitre-attack-p0-18377', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "One [TYPEFRAME](https://attack.mitre.org/software/S0263) variant decrypts an archive using an RC4 key, then decompresses and installs the decrypted malicious DLL module. Another variant decodes the embedded file by XORing it with the value \"0x35\".(Citation: US-CERT TYPEFRAME June 2018)", "external_references": [{"description": "US-CERT. (2018, June 14). MAR-10135536-12 – North Korean Trojan: TYPEFRAME. Retrieved July 13, 2018.", "source_name": "US-CERT TYPEFRAME June 2018", "url": "https://www.us-cert.gov/ncas/analysis-reports/AR18-165A"}], "id": "relationship--77b9e1c5-8241-4260-8125-4bc2e1206b9c", "modified": "2026-04-29T14:23:06.089Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7ba0fc46-197d-466d-8b9f-f1c64d5d81e5", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18377', 0, 88, '09-mitre-attack', 'retrieved', 'FB632FC9AE08E6735BFFFA4C168752C72720FAA971A797C87928264EC230588D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
