VALUES ('doc-09-mitre-attack-p0-18398', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-01T21:19:30.513Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bundlore](https://attack.mitre.org/software/S0482) creates a new key pair with ssh-keygen and drops the newly created user key in authorized_keys to enable remote login.(Citation: MacKeeper Bundlore Apr 2019)", "external_references": [{"description": "Sushko, O. (2019, April 17). macOS Bundlore: Mac Virus Bypassing macOS Security Features. Retrieved June 30, 2020.", "source_name": "MacKeeper Bundlore Apr 2019", "url": "https://mackeeper.com/blog/post/610-macos-bundlore-adware-analysis/"}], "id": "relationship--6723c87e-f60a-465f-96cd-78d63d17ba01", "modified": "2026-04-29T14:23:06.065Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7bef1b56-4870-4e74-b32a-7dd88c390c44", "spec_version": "2.1", "target_ref": "attack-pattern--6b57dc31-b814-4a03-8706-28bc20d739c4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18398', 0, 80, '09-mitre-attack', 'retrieved', '5D1FF6D891FD67B20CEAFC2433BAAE214EDC844884A4788782BA0575C5B2C591', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
