VALUES ('doc-09-mitre-attack-p0-18399', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-01T21:19:30.521Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Bundlore](https://attack.mitre.org/software/S0482) has used Python scripts to execute payloads.(Citation: MacKeeper Bundlore Apr 2019)", "external_references": [{"description": "Sushko, O. (2019, April 17). macOS Bundlore: Mac Virus Bypassing macOS Security Features. Retrieved June 30, 2020.", "source_name": "MacKeeper Bundlore Apr 2019", "url": "https://mackeeper.com/blog/post/610-macos-bundlore-adware-analysis/"}], "id": "relationship--677878af-62d4-4407-bbe6-551b7906a366", "modified": "2026-04-29T14:23:06.066Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7bef1b56-4870-4e74-b32a-7dd88c390c44", "spec_version": "2.1", "target_ref": "attack-pattern--cc3502b5-30cc-4473-ad48-42d51a6ef6d1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18399', 0, 67, '09-mitre-attack', 'retrieved', '7AB0B635CF8B469DA0025CC8D40E2946D3B46E97A4695BFB62785736FD2727B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
